INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsh5amf4qhpr4xxzelga', 'My Landscapers Inc.', 'my-landscapers-inc-1914bc', 'landscaping', '+1 416-838-2229', 'info@mylandscapers.ca', 'https://www.mylandscapers.ca/', '120 Thornway Ave, Thornhill, ON L4J 7Z3', 'CA', 'CAD', 'Vaughan', 'ON', 'L4J 7Z3', 43.8086268, -79.4589811, 25, 'business', true, true, 'free', false, 4.9, 180, 'My Landscapers Inc. — landscaping in Vaughan', '<p>Front yard and backyard landscaping for residential and commercial properties. Call My Landscapers at (416) 838-2229 for complete outdoor solutions..</p>
<p>As one of the top landscaping companies in GTA, we also offer ongoing lawn care services .</p>
<p>We are a top-rated certified landscaping company in GTA, known for exceptional customer service. We offer full landscape design and maintenance for both residential and commercial properties. Our Toronto landscapers treat every client with respect and are always available to assist you. With 100% transparent pricing and guaranteed satisfaction, you can trust us for reliable service. Stay informed with money-saving landscaping tips on our blog.</p>
