INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsh5asqpv36mwov41c17', 'RAINscapeTO', 'rainscapeto-3198f2', 'landscaping', NULL, NULL, 'https://rainscapeto.ca/', '720 Bathurst St, Toronto, ON M5S 2R4', 'CA', 'CAD', 'Toronto', 'ON', 'M5S 2R4', 43.6632744, -79.41061549999999, 25, 'business', true, true, 'free', false, 4.9, 38, 'RAINscapeTO — landscaping in Toronto', '<p>Book a 45 min consultation to learn about the best options for your property and get a no-obligation quote.</p>
<p>GreenForceTO is a green workforce development project initiated in 2021. The project, led by Transportation Services’ Green Streets program, in partnership with the Energy and Environment Division, looks to bridge the gap of maintenance of green infrastructure and horticulture in the right-of-way and build a landscape-skilled workforce. City of Toronto Transportation Services’ (TS) Green Streets, Operations and Management (O&M), Neighbourhood Projects, and Live Green Toronto collaborated with RAINscapeTO and Building Up and comprised the project management team (PMT).</p>
<p>For more information about the GreenForceTO program and the progress of our new initiatives, please refer to our annual report</p>
<p>Rainscaping includes strategies such as rain water harvesting, composting and care for the soil, organic garden management, permeable paving, rain gardens, bioswales, woodland restoration and pocket forests, and stream bank restoration if you have a creek in your garden.</p>
<p>A rain garden is a small bowl shaped area in the garden that catches water from roof…</p>', 'RAINscapeTO — landscaping in Toronto | Fieseros', 'Book RAINscapeTO for landscaping services in Toronto. Professional, reliable, and trusted by local customers. Rated 4.9★ (38 reviews).', '["landscaping"]', '{"emailSource":"none","emailVerified":false,"descriptionSource":"website_scrape","seededAt":"2026-08-06T06:39:02.401Z","seedSource":"google-places"}', 14, 'ChIJ4xquEmQ1K4gRX9cb_N_wnn0', '2026-08-06T06:39:02.403Z', '2026-08-06T06:39:02.403Z')
  ON CONFLICT ("googlePlaceId") DO NOTHING;

