INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsh5b23eal2uwfy5l8n4', 'Strathmore Commercial Landscape Management', 'strathmore-commercial-landscape-manageme-e163b3', 'landscaping', '+1 514-992-5902', NULL, 'https://www.strathmore.pro/?utm_source=google&utm_medium=wix_google_business_profile&utm_campaign=3831330598571091173', '2288 Rue de Cannes-Brûlées, LaSalle, QC H8N 2Z2', 'CA', 'CAD', 'Montréal', 'QC', 'H8N 2Z2', 45.4434405, -73.62130429999999, 25, 'business', true, true, 'free', false, 4.4, 106, 'Strathmore Commercial Landscape Management — landscaping in Montréal', '<p>Strathmore is Canada''s national commercial landscape management and snow removal company, setting the Strathmore Standard for excellence since 1963.</p>
<p>Today, we have over 250 trucks and are Canada''s fastest-growing national landscape management company.</p>
<p>Inspired by the legacy of our grandfather, Elmer Milligan, and the values instilled by our father, Danny Milligan, we are committed to upholding standards of excellence, prioritizing safety, and always striving to do what is right.</p>
<p>Strathmore is a family business that is run by Jessica Milligan (President), Gordon Milligan (VP), and Conor Milligan (VP).</p>
<p>"Great company to work for. People with class and experience. Best of the best. Highly recommended."</p>
<p>Do you enjoy working outside? Doing healthy, physical work? Being well paid, including paid holidays and overtime?</p>', 'Strathmore Commercial Landscape Management — landscaping in Montréal |', 'Book Strathmore Commercial Landscape Management for landscaping services in Montréal. Professional, reliable, and trusted by local customers. Rated 4.4★ (1', '["landscaping"]', '{"emailSource":"none","emailVerified":false,"descriptionSource":"website_scrape","seededAt":"2026-08-06T06:39:14.522Z","seedSource":"google-places"}', 6, 'ChIJmbox2O4RyUwRMykF4OOpbus', '2026-08-06T06:39:28.019Z', '2026-08-06T06:39:28.019Z')
