INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsh5b4olz11jlftt2c60', 'MTL Landscaping', 'mtl-landscaping-af0bd4', 'landscaping', '+1 514-519-5852', NULL, 'https://mtllandscaping.ca/', '784 Mnt Montrougeau, Laval, QC H7P 5K4', 'CA', 'CAD', 'Laval', 'QC', 'H7P 5K4', 45.581903200000006, -73.8157078, 25, 'business', true, true, 'free', false, 5, 8, 'MTL Landscaping — landscaping in Laval', '<p>From stunning retaining walls to elegant walkways, patios, and driveways, we bring your outdoor vision to life. Whether it’s lush grass, low-maintenance artificial turf, ambient outdoor lighting, or a cozy fire pit, our expert team transforms your space into an inviting oasis. Experience craftsmanship, quality, and care tailored just for you.</p>
<p>Welcome to MTL Landscaping, where your outdoor dreams take shape! We specialize in crafting stunning landscapes that combine beauty, functionality, and durability. Whether you’re envisioning elegant patios, walkways, or driveways, lush natural or artificial grass, or adding warmth with a fire pit and ambient outdoor lighting, we’ve got you covered. Our dedicated team works with precision and care to create spaces you’ll love for years to come. Let us transform your outdoors into an oasis that reflects your style and enhances your everyday living.</p>
<p>Our expertise include designing and constructing retaining walls, walkways, patios, and driveways, tailored to your outdoor needs. We also specialize in grass installation, artificial turf, outdoor lighting, and cozy fire pits to elevate your space.</p>', 'MTL Landscaping — landscaping in Laval | Fieseros', 'Book MTL Landscaping for landscaping services in Laval. Professional, reliable, and trusted by local customers. Rated 5.0★ (8 reviews).', '["landscaping"]', '{"emailSource":"none","emailVerified":false,"descriptionSource":"website_scrape","seededAt":"2026-08-06T06:39:17.877Z","seedSource":"google-places"}', 5, 'ChIJY0OGhSOCNW4RHgrK_QqQ3RI', '2026-08-06T06:39:28.019Z', '2026-08-06T06:39:28.019Z')
