INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsh5bf2orkog1srhkl2o', 'Paysagiste DICO', 'paysagiste-dico-b10c4b', 'landscaping', '+1 514-889-5663', 'info@paysagistedicomontreal.com', 'https://paysagistedicomontreal.com/', 'Montreal, QC H1E 3E2', 'CA', 'CAD', 'Montreal', 'QC', 'H1E 3E2', 45.6316126, -73.588065, 25, 'business', true, true, 'free', false, 4.9, 18, 'Paysagiste DICO — landscaping in Montreal', '<p>DICO is landscaping company that services Montreal and surrounding areas. We bring our client’s outdoor spaces to life, while maintaining great and trustworthy relationships.</p>
<p>Our specialties include asphalt services, lawn maintenance, and we specialize in small scale Unistone projects such as walkways, patios, repairs etc.</p>
<p>Whether it’s paving a small driveway, repairing patches or sealing. We have it covered.</p>
<p>DICO is a landscaping/ construction company that services Montreal and surrounding areas. Originally started as a lawn care mowing business, we have grown to provide other services in the asphalt area and the interlocking paver area. Our core values revolve around building great relationships with our clients even after work has been completed. Trust and reliability above all.</p>
<p>Commercial/ residential lawn maintenance. Asphalt paving, repairs and maintenance. Small scale paver patios, walkways, retaining walls etc. Plantations and other.</p>', 'Paysagiste DICO — landscaping in Montreal | Fieseros', 'Book Paysagiste DICO for landscaping services in Montreal. Professional, reliable, and trusted by local customers. Rated 4.9★ (18 reviews).', '["landscaping"]', '{"emailSource":"website_scrape","emailVerified":false,"descriptionSource":"website_scrape","seededAt":"2026-08-06T06:39:31.344Z","seedSource":"google-places"}', 5, 'ChIJExMyRdQfyUwRHEDUIZR17dg', '2026-08-06T06:39:35.437Z', '2026-08-06T06:39:35.437Z')
