INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsh5c81vw58afx55e8ji', 'Calgary Landscaping', 'calgary-landscaping-1f8074', 'landscaping', '+1 403-237-6300', NULL, 'https://calgarylandscaping.com/', '259 Midpark Way SE Ste 250, Calgary, AB T2X 1M2', 'CA', 'CAD', 'Calgary', 'AB', 'T2X 1M2', 50.9120717, -114.06364789999999, 25, 'business', true, true, 'free', false, 4.7, 61, 'Calgary Landscaping — landscaping in Calgary', '<p>Our integrated landscape design and construction process leaves “no stone unturned”, ensuring every detail is planned and executed as your outdoor living space takes shape.</p>
<p>As leading landscaping contractors in Calgary , we specialize in professional landscape design and high-durability Calgary retaining wall construction</p>
<p>Residential landscape construction delivered with proper planning, sequencing, and build quality for long term performance.</p>
