  VALUES ('cmsh5dkkxa4k6e1rvvmg2', 'The Details Landscaping & Renovations Inc.', 'the-details-landscaping-renovations-inc-162e1c', 'landscaping', '+1 204-998-0227', 'gino@thedetailswpg.com', 'https://www.thedetailswpg.com/', '199 Shoreline Dr, Winnipeg, MB R3P 2J9', 'CA', 'CAD', 'Winnipeg', 'MB', 'R3P 2J9', 49.8347743, -97.1924099, 25, 'business', true, true, 'free', false, 5, 17, 'The Details Landscaping & Renovations Inc. — landscaping in Winnipeg', '<p>The Details Landscaping and Renovations is a leading Landscaping and Renovation company based out of Winnipeg, Manitoba. We strive to be recognized for quality, attentiveness to details, excellent client rapport and efficiency in the delivery of all landscaping and renovation projects. Our mission is to have homeowners fall in love with their homes while increasing curb appeal and property value.</p>', 'The Details Landscaping & Renovations Inc. — landscaping in Winnipeg |', 'Book The Details Landscaping & Renovations Inc. for landscaping services in Winnipeg. Professional, reliable, and trusted by local customers. Rated 5.0★ (1', '["landscaping"]', '{"emailSource":"website_scrape","emailVerified":false,"descriptionSource":"website_scrape","seededAt":"2026-08-06T06:41:11.793Z","seedSource":"google-places"}', 8, 'ChIJ88lmwJCt64MR5YpajEcuVrM', '2026-08-06T06:41:19.265Z', '2026-08-06T06:41:19.265Z')
