INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsh5e4l2el5oy3ze5gme', 'Paysage Urbain - Aménagement paysager et terrassement urbain', 'paysage-urbain-am-nagement-paysager-et-t-6862e7', 'landscaping', '+1 418-929-0329', NULL, 'https://paysageurbain.ca/', 'Rue Hermine, Québec, QC G1K 1Y8', 'CA', 'CAD', 'Québec', 'QC', 'G1K 1Y8', 46.809767199999996, -71.23361249999999, 25, 'business', true, true, 'free', false, 4.4, 21, 'Paysage Urbain - Aménagement paysager et terrassement urbain — landscaping in Québec', '<p>Accès sur le développement des aménagements responsables et perméables, nous offrons des solutions alternatives aux aménagements traditionnels et nous avons les outils nécessaires pour répondre aux besoins spécifiques des quartiers centraux.</p>
<p>Nous offrons également nos services pour tous les autres projets de terrassement et d''aménagement paysager.</p>
<p>Il se doit d''être réfléchi, en harmonie avec votre environnement et personnalisé en fonction de votre style de vie et de vos besoins.</p>
