  VALUES ('cmsh5eg7lda0ulw46u5ud', 'Entretiens extérieurs CAG inc', 'entretiens-ext-rieurs-cag-inc-4cbe9a', 'landscaping', '+1 418-570-6457', NULL, 'https://entretiensexterieurscag.com/', '1510 Rue Semple, Québec, QC G1N 4B4', 'CA', 'CAD', 'Québec', 'QC', 'G1N 4B4', 46.8011883, -71.26591239999999, 25, 'business', true, true, 'free', false, 4.7, 14, 'Entretiens extérieurs CAG inc — landscaping in Québec', '<p>Faites appel à nous pour un bon ménage d''automne: • Nettoyage complet du terrain • Taille de haies et arbustes • Ramassage de feuilles</p>
