INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsh5eoldhtd7rvvef2do', 'Émondage BOIS-VERT', 'mondage-bois-vert-43e1df', 'landscaping', '+1 418-271-4051', NULL, 'http://www.emondageboisvert.com/', '366 8e Rue, Québec, QC G1L 2P1', 'CA', 'CAD', 'Québec', 'QC', 'G1L 2P1', 46.8255887, -71.22753279999999, 25, 'business', true, true, 'free', false, 5, 195, 'Émondage BOIS-VERT — landscaping in Québec', '<p>Quand on parle d’élagage, on fait référence à de gros arbres ou d’arbres matures, mais relativement à l’émondage, on entretiendra un petit arbre ou un arbre fruitier. Plus il est jeune, plus il est facile...</p>
<p>Parfois un simple élagage ne suffira pas à résoudre un problème de santé de vos arbres ou à réduire les dangers pour votre environnement urbain. Nos arboriculteurs...</p>
<p>Notre service d''essouchement ne cause pas de dommages au terrain, car l''essoucheuse est légère et elle est équipée de pneus. Les copeaux de bois sont...</p>
<p>Vous remarquez que vos haies de cèdres prennent de l''ampleur et perdent leur structure de base qui avait été si bien travaillée ? Pour contrer cela il est important...</p>
<p>L’élagage est une taille exceptionnelle qui consiste en la coupe de certaines branches mortes ou vivantes d''un arbre pour en orienter ou limiter le développement.</p>
<p>Dans le domaine de la sylviculture, l’abattage d''un arbre consiste à le couper à la base pour provoquer sa chute et ensuite permettre le retrait du site et son exploitation. Il s''agit d''une étape importante de l''exploitation forestière.</p>', 'Émondage BOIS-VERT — landscaping in Québec | Fieseros', 'Book Émondage BOIS-VERT for landscaping services in Québec. Professional, reliable, and trusted by local customers. Rated 5.0★ (195 reviews).', '["landscaping"]', '{"emailSource":"none","emailVerified":false,"descriptionSource":"website_scrape","seededAt":"2026-08-06T06:42:03.649Z","seedSource":"google-places"}', 5, 'ChIJn6f6jHyXuEwRQeL8uFcMUqQ', '2026-08-06T06:42:08.314Z', '2026-08-06T06:42:08.314Z')
  ON CONFLICT ("googlePlaceId") DO NOTHING;

INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsh5eofsvvpks2w7mi37', 'Amenagement Paysagiste-Prtgl', 'amenagement-paysagiste-prtgl-8f0dcc', 'landscaping', '+1 418-842-8473', 'info@amenduportugal.ca', 'http://www.amenduportugal.ca/', '9725 Rue de Budapest, Québec, QC G2B 0A2', 'CA', 'CAD', 'Québec', 'QC', 'G2B 0A2', 46.847412, -71.3432345, 25, 'business', true, true, 'free', false, 3.7, 11, 'Amenagement Paysagiste-Prtgl — landscaping in Québec', '<p>Donnez un nouveau souffle &agrave; votre espace ext&eacute;rieur gr&acirc;ce &agrave; notre savoir-faire en am&eacute;nagement paysager</p>
<p>L''am&eacute;nagement de votre propri&eacute;t&eacute;, de l''espace ext&eacute;rieur autour de votre maison, doit &ecirc;tre vu comme un investissement. Cela dit, pour que ce dernier soit pleinement profitable, il importe d''en confier la conception et la r&eacute;alisation &agrave; des experts, &agrave; des paysagistes professionnels .</p>
<p>Parce qu''ils connaissent bien les v&eacute;g&eacute;taux, les techniques horticoles, le drainage, les sols, etc., les paysagistes accomplissent des am&eacute;nagements durables et harmonieux. C''est ainsi que votre projet se transforme en bon investissement . Bien fait, un am&eacute;nagement paysager :</p>
<p>rehaussera l''apparence g&eacute;n&eacute;rale du b&acirc;timent, son esth&eacute;tique, son impact visuel</p>
<p>optimisera la fonctionnalit&eacute; de votre terrain en "cr&eacute;ant de l''espace"</p>
<p>personnalisera certaines zones selon vos go&ucirc;ts et pr&eacute;f&eacute;rences (intimit&eacute;, ambiance…)</p>', 'Amenagement Paysagiste-Prtgl — landscaping in Québec | Fieseros', 'Book Amenagement Paysagiste-Prtgl for landscaping services in Québec. Professional, reliable, and trusted by local customers. Rated 3.7★ (11 reviews).', '["landscaping"]', '{"emailSource":"website_scrape","emailVerified":false,"descriptionSource":"website_scrape","seededAt":"2026-08-06T06:42:03.448Z","seedSource":"google-places"}', 8, 'ChIJ4b1k2W2YuEwRGd_y2EG5M40', '2026-08-06T06:42:08.314Z', '2026-08-06T06:42:08.314Z')
  ON CONFLICT ("googlePlaceId") DO NOTHING;

