INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsh5eyb7fmrg7l61rgub', 'Gelderman Landscape Services', 'gelderman-landscape-services-566fb9', 'landscaping', '+1 905-689-5433', NULL, 'https://www.gelderman.com/?utm_source=gmb&utm_medium=organic', '831 Centre Rd, Hamilton, ON L9N 2Z7', 'CA', 'CAD', 'Hamilton', 'ON', 'L9N 2Z7', 43.3524856, -79.92694089999999, 25, 'business', true, true, 'free', false, 4.7, 445, 'Gelderman Landscape Services — landscaping in Hamilton', '<p>Everyone talks about service these days, and many don’t deliver. To us, that’s unacceptable. So as we work to bring beauty to the urban landscape, we aim to change that.</p>
<p>Jan Gelderman, a Dutch immigrant, founded Jan Gelderman Landscaping in Burlington with just $7.14 worth of tools and a 1948 Jeep Willy.</p>
<p>Today, the company is called Gelderman Landscape Services to better describe the diversity of services in Commercial Landscape Management and Residential Construction. Now onto the 3rd generation, we’re still a family company, and we care about the communities we work in.</p>
<p>Beginning in Burlington , we‘ve spread to Mississauga in the east, Kitchener-Waterloo in the west, and as far north as Guelph . Wherever you are, we’re right where you need us.</p>', 'Gelderman Landscape Services — landscaping in Hamilton | Fieseros', 'Book Gelderman Landscape Services for landscaping services in Hamilton. Professional, reliable, and trusted by local customers. Rated 4.7★ (445 reviews).', '["landscaping"]', '{"emailSource":"none","emailVerified":false,"descriptionSource":"website_scrape","seededAt":"2026-08-06T06:42:16.243Z","seedSource":"google-places"}', 13, 'ChIJJaumd1F9K4gRjNjphjJmcJ4', '2026-08-06T06:42:24.418Z', '2026-08-06T06:42:24.418Z')
