INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsh5fdicjvkyaxzcujmq', 'E.S. McInnes & Sons', 'e-s-mcinnes-sons-bf64bf', 'landscaping', '+1 902-452-3800', NULL, 'https://www.esmcinnesgardener.com/', '946 Ivanhoe St, Halifax, NS B3H 2X1', 'CA', 'CAD', 'Halifax', 'NS', 'B3H 2X1', 44.6330057, -63.576482199999994, 25, 'business', true, true, 'free', false, 5, 13, 'E.S. McInnes & Sons — landscaping in Halifax', '<p>We offer a full range of landscape services from seasonal fundamentals to specialized projects. E.S. McInnes & Sons provides effective and practical solutions so your outdoor space can realize its full potential. We bring muscle, imagination and TLC wherever it''s needed.</p>
<p>We do landscape basics: spring and fall clean-up; weeding; shrub and tree trimming, pruning and shaping.</p>
<p>We create beautiful, thriving gardens tailored to your preferences; enhance the connection between the home and the yard; harmonize sight lines, beds, borders and boundaries.</p>
<p>We use local natural stone to create durable and stylish patios, walkways, stairs and retaining walls to give your garden a beautiful backbone and structure.</p>
<p>We grow flowers for weddings and special occassions for long-lasting bunches and bouquets such as daffodils, peonies, gladiolus, zinnias and more.</p>
<p>"E.S. McInnes & Sons transformed our backyard into an oasis! Their team was professional, detailed, and truly exceeded our expectations. Highly recommend their landscaping services in Halifax."</p>', 'E.S. McInnes & Sons — landscaping in Halifax | Fieseros', 'Book E.S. McInnes & Sons for landscaping services in Halifax. Professional, reliable, and trusted by local customers. Rated 5.0★ (13 reviews).', '["landscaping"]', '{"emailSource":"none","emailVerified":false,"descriptionSource":"website_scrape","seededAt":"2026-08-06T06:42:35.940Z","seedSource":"google-places"}', 5, 'ChIJ5ar16UAiWksR_4NQ4syy558', '2026-08-06T06:42:43.594Z', '2026-08-06T06:42:43.594Z')
