INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsh5gpld4wfqvljdho19', 'Confort Expert Inc', 'confort-expert-inc-7b74da', 'hvac', '+1 514-640-7711', NULL, 'https://www.confortexpert.com/', '9771 Bd Métropolitain E, Anjou, QC H1J 0A4', 'CA', 'CAD', 'Montréal', 'QC', 'H1J 0A4', 45.625080999999994, -73.5495907, 25, 'business', true, true, 'free', false, 4.3, 1857, 'Confort Expert Inc — hvac in Montréal', '<p>Nous sommes l''une des rares entreprises dans le domaine qui possède tous les permis requis par la Régie du bâtiment du Québec, ce qui nous permet de vous offrir des solutions clé en main.</p>
<p>Nous sommes également l’une des rares entreprises dans l’industrie détenant le permis requis par l’office de la protection du consommateur.</p>
