INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsh5i4kg94n3utdmaisp', 'Expert Hvac Solutions Ltd', 'expert-hvac-solutions-ltd-330791', 'hvac', '+1 403-274-2621', 'info@experthvac.ca', 'https://experthvac.ca/', '1112 40 Ave NE Bay #6, Calgary, AB T2E 5T8', 'CA', 'CAD', 'Calgary', 'AB', 'T2E 5T8', 51.089281400000004, -114.0363393, 25, 'business', true, true, 'free', false, 4.9, 954, 'Expert Hvac Solutions Ltd — hvac in Calgary', '<p>Just like your car, your furnace needs to be properly tuned up every year. Join our VIP Program and have the peace of mind that your home is ready for the cold Canadian winter.</p>
<p>When an emergency strikes, we’ve got your back. Part of our exceptional customer service philosophy is being there for you when you need us the most: during an emergency!</p>
<p>Call us if your furnace breaks down, your air conditioner gives out, or you experience any other HVAC malfunctions. We have 24-hour on-call technicians available to provide reliable heating and cooling repairs.</p>
