INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsh5wy3tj8dqh7rs67ak', 'Hamilton Home Comfort', 'hamilton-home-comfort-abd586', 'hvac', '+1 905-643-0981', NULL, 'https://hamiltonhomecomfort.com/', '335 Fruitland Rd, Stoney Creek, ON L8E 5M8', 'CA', 'CAD', 'Hamilton', 'ON', 'L8E 5M8', 43.224213, -79.69978600000002, 25, 'business', true, true, 'free', false, 4.8, 397, 'Hamilton Home Comfort — hvac in Hamilton', '<p>From emergency repairs to complete system upgrades, we provide comprehensive comfort solutions for every Hamilton area home. Our family business delivers results you can trust.</p>
