INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsh5z5k5w6w80fi2zs6j', 'CF Electrical Services', 'cf-electrical-services-004ca2', 'electrical', '+1 778-910-4772', 'info@cfelectrical.ca', 'https://cfelectrical.ca/', '526 Clark Dr, Vancouver, BC V5L 3H7', 'CA', 'CAD', 'Vancouver', 'BC', 'V5L 3H7', 49.280091399999996, -123.0769323, 25, 'business', true, true, 'free', false, 4.9, 74, 'CF Electrical Services — electrical in Vancouver', '<p>We do strata electrical consulting and we do it well — the plans your strata is required to have, and the management to see them through. That''s it. That''s the focus.</p>
